<script lang="ts">
 import {tick} from 'svelte';
 import type {TurnPlayer} from './turn';
 import {automationPreview} from './automation-preview';
 import {BASIC_AUTOMATION_AWARDS,automationScore} from './automation-scoring';
 let {player}:{player:TurnPlayer}=$props();
 let sideways=$state(false),angled=$state(false);
 let panel=$state<'Track'|'Food'|'Ore'|'Rules'>('Track');
 let reader=$state<HTMLDialogElement>(undefined!),opener=$state<HTMLButtonElement>(undefined!);
 const food=$derived(automationPreview(player,'food'));
 const ore=$derived(automationPreview(player,'ore'));
 async function open(){panel='Track';reader.style.setProperty('--reader-angle',getComputedStyle(opener).getPropertyValue('--reader-angle')||'0deg');const angle=parseFloat(getComputedStyle(reader).getPropertyValue('--reader-angle'))||0;sideways=angle%180!==0;angled=angle%90!==0;await tick();document.body.append(reader);reader.showModal();}
 function trap(event:KeyboardEvent){if(event.key!=='Tab')return;event.stopPropagation();const controls=[...reader.querySelectorAll<HTMLElement>('button,[tabindex="0"]')];if(event.shiftKey&&document.activeElement===controls[0]){event.preventDefault();controls.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===controls.at(-1)){event.preventDefault();controls[0]?.focus();}}
 function placeReader(host:HTMLDivElement){const node=host.querySelector('dialog')!;document.body.append(node);return {destroy:()=>node.remove()};}
</script>
<button class="inspect" bind:this={opener} aria-haspopup="dialog" onclick={open}>Inspect permanent automation ↗</button>
<div use:placeReader>
 <dialog data-e2e-layout bind:this={reader} class="automation-reader" class:sideways class:angled aria-label="Permanent automation" onkeydown={trap} onclose={()=>opener?.focus({preventScroll:true})}>
  <header><div><p>PRODUCTION ENGINE</p><h2>Permanent automation</h2></div><button onclick={()=>reader.close()} aria-label="Close automation inspection">Close ×</button></header>
  <nav aria-label="Automation views">{#each ['Track','Food','Ore','Rules'] as view}<button aria-pressed={panel===view} onclick={()=>panel=view as typeof panel}>{view==='Food'||view==='Ore'?`Next ${view}`:view}</button>{/each}</nav>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex (Named internal reader supports bounded keyboard scrolling.) -->
  <div class="reader-body" role="region" aria-label="Automation details" tabindex="0">
   {#if panel==='Track'}
    <p class="level"><strong>{player.automation}</strong> permanent {player.automation===1?'level':'levels'} <span class="score" aria-label={`Cumulative endgame Automation contribution: ${automationScore(player.automation)} VP`}><b>{automationScore(player.automation)} VP</b> at game end</span></p>
    <ol class="permanent-track" aria-label="Seven printed automation positions">{#each BASIC_AUTOMATION_AWARDS as award,index}{@const level=index+1}<li class:filled={level<=player.automation} aria-label={`Level ${level}: ${level<=player.automation?'filled permanently':'empty'}; ${award} endgame VP`}><span aria-hidden="true">{level<=player.automation?'●':'◌'}</span><b>{level}</b><small>{award} VP</small></li>{/each}</ol>
    {#if player.automation>7}<p class="overflow">+{player.automation-7} beyond the printed track · {player.automation-7} additional VP</p>{/if}
    <p>Automation stays permanently. Control outposts on the Exploration board can return.</p>
   {:else if panel==='Food'||panel==='Ore'}
    {@const effect=panel==='Food'?food:ore}
    <article class="next-effect"><h3>{panel} → level {effect.nextLevel}</h3><span class="marker">{effect.marker==='placeholder'?'✧ Placeholder':'● Production disc'}</span><p>{#if effect.marker==='placeholder'}No matching discs remain. Add a permanent placeholder; production capacity stays unchanged.{:else}Move the leftmost {panel} disc. {#if panel==='Food'}Expose {effect.newlyExposed[0]?.letter?`column ${effect.newlyExposed[0].letter}`:'a blank slot'}.{:else}Expose one additional Ore yield.{/if}{/if}</p><strong>{panel==='Food'?`${effect.populationBefore} → ${effect.populationAfter} Population from full growth`:`${effect.oreBefore} → ${effect.oreAfter} Ore production`}</strong><small>{effect.pointsBefore} → {effect.pointsAfter} endgame VP · cumulative track awards</small><p class="reference">Reference only · inspection spends and gains nothing.</p></article>
   {:else}
    <h3>Permanent means permanent</h3>
    <p>Automation discs never return. When a matching production track is exhausted, use a placeholder.</p>
    <p>A later returned production disc does not replace an existing placeholder.</p>
    <p>Score the printed awards cumulatively; each level beyond seven adds 1 VP.</p>
    <p>Food draws only from its matching nonempty Supply column. Collect yields by choosing a production branch on your turn.</p>
   {/if}
  </div>
 </dialog>
</div>
<style>
 .inspect{min-height:44px;padding:9px 14px;border:1px solid #a78d58;border-radius:5px;background:linear-gradient(#f4ead1,#dac69e);color:#302b22;font:600 15px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}
 .automation-reader{transform:rotate(var(--reader-angle,0deg));width:min(850px,94vw);max-height:90dvh;padding:0;border:2px solid #a88a50;border-radius:15px;background:linear-gradient(130deg,#f5edd9,#d9c8a5);color:#302b23;box-shadow:0 20px 80px #000c,inset 0 0 0 5px #fff4;font:16px/1.4 'Atkinson Hyperlegible',sans-serif}
 .automation-reader[open]{display:grid;grid-template-rows:auto auto minmax(0,1fr);grid-template-columns:minmax(0,1fr)}.automation-reader>*{min-width:0}.automation-reader header>div{min-width:0}.automation-reader::backdrop{background:#071015dc}.automation-reader header{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 22px;border-bottom:1px solid #947b4b;background:#eee1c4;z-index:1}.automation-reader header p{font-size:11px;letter-spacing:.16em;margin:0}.automation-reader h2{font:600 30px 'Cormorant Garamond',serif;margin:0}.automation-reader nav{display:flex;gap:8px;padding:12px 20px;border-bottom:1px solid #9c835755}.automation-reader nav button{flex:1;min-width:0;min-height:44px;border:1px solid #947b4b;border-radius:5px;background:#ecdfc0;color:#302b22;font:600 14px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}.automation-reader nav button[aria-pressed="true"]{background:#293f39;color:#fff0ce;box-shadow:inset 0 0 0 2px #cfb576}.automation-reader header button{white-space:nowrap;flex-shrink:0;min-width:80px;min-height:44px;border:1px solid #8d7445;border-radius:5px;background:#293735;color:#fff0ce;font:inherit;cursor:pointer}.reader-body{padding:20px 24px;overflow:auto;min-height:0;scrollbar-color:#8b7446 #e6d6b6}.level{display:flex;align-items:baseline;flex-wrap:wrap;gap:8px 12px;margin:0}.level .score{margin-left:auto;font-size:.875em}.level strong{font-size:42px;color:#1d5d54}.permanent-track{display:flex;list-style:none;padding:12px;gap:12px;background:#263331;border:3px solid #b59b67;border-radius:12px;box-shadow:inset 0 3px 10px #0009}.permanent-track li{flex:1;min-width:0;text-align:center;color:#d7c49c;display:grid;gap:3px}.permanent-track li small{font-size:.875em;white-space:nowrap}.score{color:#275e54}.permanent-track li span{display:grid;place-content:center;border-radius:50%;aspect-ratio:1;border:2px solid #9a8355;background:#121e1d;font-size:36px}.permanent-track .filled span{color:#e6b963;background:radial-gradient(circle at 35% 25%,#f0cf86,#8b6330);text-shadow:0 2px 3px #0007;box-shadow:0 3px 4px #0008}.next-effect{border:1px solid #a68c58;padding:15px;border-radius:8px;background:#fff6;box-shadow:0 3px 6px #432a191c}.next-effect h3{font-size:21px;margin:0 0 8px}.next-effect p{margin:10px 0}.next-effect strong,.next-effect small{display:block}.marker{font-weight:700;color:#256055}.reference{font-size:13px;margin:12px 0 0!important}.overflow{font-weight:700;color:#275e54}button:focus-visible,.reader-body:focus-visible{outline:3px solid #237f75;outline-offset:3px}.automation-reader.sideways{width:min(850px,80vmin);max-height:68vmin}.automation-reader.angled{width:min(850px,68vmin);max-height:64vmin}.angled .reader-body{padding:12px 18px}.angled .level strong{font-size:30px}.angled .permanent-track{padding:8px;gap:7px;margin:10px 0}.angled .reader-body>p{font-size:14px;line-height:1.3;margin:10px 0}.angled .next-effect{padding:12px}.angled .next-effect p{font-size:14px;line-height:1.3}.angled h3{margin-top:0}@media(max-width:600px){.reader-body{padding:15px}.permanent-track{gap:5px;padding:8px}.permanent-track li small{font-size:.875em;white-space:nowrap}.score{color:#275e54}.permanent-track li span{font-size:24px}.automation-reader header{padding:12px 15px}.automation-reader h2{font-size:26px}}
@media(min-width:2200px){.automation-reader{width:1150px;font-size:24px}.automation-reader.angled{width:min(1150px,68vmin)}.automation-reader.sideways:not(.angled){width:min(1150px,80vmin)}.automation-reader header{padding:24px 30px}.automation-reader h2{font-size:44px}.automation-reader header p{font-size:16px}.automation-reader nav{padding:16px 30px;gap:14px}.automation-reader nav button{font-size:22px;min-height:60px}.reader-body,.angled .reader-body{padding:28px 32px}.level strong,.angled .level strong{font-size:60px}.permanent-track,.angled .permanent-track{padding:18px;gap:18px;margin:20px 0}.permanent-track li small{font-size:.875em;white-space:nowrap}.score{color:#275e54}.permanent-track li span{font-size:54px}.angled .reader-body>p,.angled .next-effect p{font-size:24px;line-height:1.4}.next-effect h3{font-size:30px}.next-effect,.angled .next-effect{padding:24px}.reference{font-size:20px}}
</style>
